        const getDefaultSectionsForStoreType = (storeType) => {
            const pick = (ids) => ECOMMERCE_CATEGORIES
                .filter(c => ids.includes(c.id))
                .map(c => ({ id: c.id, label: c.labelAr, labelEn: c.labelEn, icon: c.icon }));
            if (storeType === 'paint_agency' || storeType === 'paint') {
                return pick(['paint', 'interior_paint', 'exterior_paint', 'putty_primer', 'decor_paint', 'tools']);
            }
            if (storeType === 'gypsum_board') {
                return pick(['gypsum_board', 'gypsum_profiles', 'putty_primer', 'tools']);
            }
            if (storeType === 'decor') {
                return pick(['decor', 'decor_paint', 'gypsum_board', 'tools']);
            }
            if (storeType === 'general') {
                return pick(['tools', 'putty_primer']);
            }
            return pick(['paint', 'gypsum_board', 'decor', 'tools']);
        };

        const getStoreSectionsList = (store, storeProds = []) => {
            const hasExplicitSections = Array.isArray(store?.customSections) && store.customSections.length > 0;
            if (hasExplicitSections) {
                return store.customSections
                    .filter(s => s && s.id && s.label)
                    .map(s => ({
                        id: s.id,
                        label: s.label,
                        labelEn: s.labelEn || s.label,
                        icon: s.icon || '📂'
                    }));
            }
            const baseList = getDefaultSectionsForStoreType(store?.storeType || 'both');
            const seen = new Set(baseList.map(s => s.id));
            const merged = [...baseList];
            if (Array.isArray(storeProds)) {
                for (const p of storeProds) {
                    if (p?.category && !seen.has(p.category)) {
                        seen.add(p.category);
                        const known = ECOMMERCE_CATEGORIES.find(c => c.id === p.category);
                        merged.push({
                            id: p.category,
                            label: p.categoryLabel || known?.labelAr || 'قسم إضافي',
                            labelEn: p.categoryLabel || known?.labelEn || 'Other',
                            icon: known?.icon || p.icon || '📂'
                        });
                    }
                }
            }
            return merged;
        };

